window.PORTFOLIO_PAGE_TRANSLATIONS = [["Jinhyun An \u2014 Industrial AI / Data Engineering Portfolio","\uc548\uc9c4\ud604 \u2014 \uc0b0\uc5c5 AI / \ub370\uc774\ud130 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ud3ec\ud2b8\ud3f4\ub9ac\uc624"],["\u2190 Back to the new portfolio","\u2190 \uc0c8\ub85c\uc6b4 \ud3ec\ud2b8\ud3f4\ub9ac\uc624\ub85c \ub3cc\uc544\uac00\uae30"],["Industrial AI \u00b7 Data Engineering","\uc0b0\uc5c5 AI \u00b7 \ub370\uc774\ud130 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1"],["An engineer who has built power plants","\ud50c\ub79c\ud2b8\ub97c \uc9c0\uc5b4\ubcf8 \uc5d4\uc9c0\ub2c8\uc5b4\uac00"],["now builds AI systems","AI \uc2dc\uc2a4\ud15c\uc744 \uc9c1\uc811 \ub9cc\ub4ed\ub2c8\ub2e4"],["10+ years designing power-plant systems on EPC mega-projects \u2014 now building the AI/data systems that make construction projects measurable: leakage-aware risk models, deterministic tool-calling agents, and offline-first LLM apps for air-gapped sites.","EPC \ub300\ud615 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \ubc1c\uc804\uc18c \uc2dc\uc2a4\ud15c\uc744 \uc124\uacc4\ud55c 10\ub144 \uc774\uc0c1\uc758 \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c, \uc774\uc81c \uac74\uc124 \ud504\ub85c\uc81d\ud2b8\ub97c \uce21\uc815 \uac00\ub2a5\ud558\uac8c \ud558\ub294 AI\u00b7\ub370\uc774\ud130 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4ed\ub2c8\ub2e4. \ub370\uc774\ud130 \ub204\uc218\ub97c \uace0\ub824\ud55c \ub9ac\uc2a4\ud06c \ubaa8\ub378, \uacb0\uc815\ub860\uc801 \ub3c4\uad6c\ub97c \ud638\ucd9c\ud558\ub294 \uc5d0\uc774\uc804\ud2b8, \ud3d0\uc1c4\ub9dd \ud604\uc7a5\uc744 \uc704\ud55c \uc624\ud504\ub77c\uc778 \uc6b0\uc120 LLM \uc571\uc744 \uac1c\ubc1c\ud569\ub2c8\ub2e4."],["Data \u00b7 ML","\ub370\uc774\ud130 \u00b7 \uba38\uc2e0\ub7ec\ub2dd"],["ML projects built on public data and restored algorithms, earning trust through reproducible validation","\uacf5\uac1c \ub370\uc774\ud130\uc640 \uacfc\uac70 \uc54c\uace0\ub9ac\uc998\uc73c\ub85c \uc7ac\ud604\ud558\uace0, \uac80\uc99d\uc73c\ub85c \uc2e0\ub8b0\ub97c \ub9cc\ub4dc\ub294 ML \ud504\ub85c\uc81d\ud2b8"],["Estimated 8 days","\uc608\uc0c1 8\uc77c"],["High risk 64%","\uace0\uc704\ud5d8 64%"],["Cohort p90 91 days","\ucf54\ud638\ud2b8 p90 91\uc77c"],["\u2192 High risk of long lead times: start permitting ahead of the construction critical path","\u2192 \uc7a5\ub0a9\uae30 \uace0\uc704\ud5d8\uad70: \ucc29\uacf5 \ud06c\ub9ac\ud2f0\uceec \ud328\uc2a4\ubcf4\ub2e4 \uc55e\uc11c \uc778\ud5c8\uac00 \ucc29\uc218 \ud544\uc694"],["FLAGSHIP","\ub300\ud45c \ud504\ub85c\uc81d\ud2b8"],["construction readiness \u00d7 ML \u00d7 agent \u00b7 2026.06","\ucc29\uacf5 \uc900\ube44\ub3c4 \u00d7 ML \u00d7 \uc5d0\uc774\uc804\ud2b8 \u00b7 2026.06"],["Predicts pre-construction readiness friction from 227K Chicago building permits: DuckDB ingest \u2192 leakage-tested features \u2192 LightGBM regression + group-relative risk classification \u2192 SHAP \u2192 a deterministic-tools diagnosis agent that outputs decision-ready risk cards. Reports an honest negative result (backlog features hurt under temporal drift) instead of hiding it.","\uc2dc\uce74\uace0 \uac74\ucd95 \uc778\ud5c8\uac00 227K\uac74\uc73c\ub85c \ucc29\uacf5 \uc900\ube44\uc758 \uc7a5\uc560 \uc694\uc778\uc744 \uc608\uce21\ud569\ub2c8\ub2e4. DuckDB \uc218\uc9d1 \u2192 \ub204\uc218 \uac80\uc99d \ud53c\ucc98 \u2192 LightGBM \ud68c\uadc0 + \uadf8\ub8f9 \uc0c1\ub300 \ub9ac\uc2a4\ud06c \ubd84\ub958 \u2192 SHAP \u2192 \uacb0\uc815\ub860\uc801 \ub3c4\uad6c\ub97c \ud65c\uc6a9\ud574 \uc758\uc0ac\uacb0\uc815\uc6a9 \ub9ac\uc2a4\ud06c \uce74\ub4dc\ub97c \ucd9c\ub825\ud558\ub294 \uc9c4\ub2e8 \uc5d0\uc774\uc804\ud2b8\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4. \uc2dc\uac04\uc5d0 \ub530\ub978 \ub370\uc774\ud130 \ubcc0\ud654\uc5d0\uc11c \uc801\uccb4\ub7c9 \ud53c\ucc98\uac00 \uc131\ub2a5\uc744 \ub0ae\ucd98 \ubd80\uc815 \uacb0\uacfc\ub3c4 \uc228\uae30\uc9c0 \uc54a\uace0 \ubcf4\uace0\ud569\ub2c8\ub2e4."],["Frames pre-construction permit delays as construction-readiness signals, reproducing every step in code: collection \u2192 cleaning \u2192 prediction \u2192 explanation \u2192 diagnostic cards. The analysis prioritizes practical reliability through temporal validation, leakage guards and group-relative risk labels.","\ucc29\uacf5 \uc804 \uc778\ud5c8\uac00 \uc9c0\uc5f0 \ub9ac\uc2a4\ud06c\ub97c \"\uac74\uc124 readiness \uc2e0\ud638\"\ub85c \ud504\ub808\uc774\ubc0d\ud574 \uc218\uc9d1\u2192\uc815\uc81c\u2192\uc608\uce21\u2192\uc124\uba85\u2192\uc9c4\ub2e8 \uce74\ub4dc\uae4c\uc9c0 \uc804 \ub2e8\uacc4\ub97c \ucf54\ub4dc\ub85c \uc7ac\ud604. \uc2dc\uac04\ubd84\ud560 \uac80\uc99d, \ub204\uc218 \ucc28\ub2e8 \ud14c\uc2a4\ud2b8, \uadf8\ub8f9 \uc0c1\ub300 \ub9ac\uc2a4\ud06c \ub77c\ubca8 \ub4f1 \ud604\uc5c5 \uc2e0\ub8b0\uc131 \uc911\uc2ec \ub370\uc774\ud130 \ubd84\uc11d."],["tool-calling agent","\ub3c4\uad6c \ud638\ucd9c \uc5d0\uc774\uc804\ud2b8"],["227K rows","227K\ud589"],["pytest leakage guards","pytest \ub204\uc218 \ubc29\uc9c0 \uac80\uc99d"],["Interactive presentation \u2192","\uc778\ud130\ub799\ud2f0\ube0c \ud504\ub808\uc820\ud14c\uc774\uc158 \u2192"],["Live agent playground \u2192","\ub77c\uc774\ube0c \uc5d0\uc774\uc804\ud2b8 \ud50c\ub808\uc774\uadf8\ub77c\uc6b4\ub4dc \u2192"],["2013 thesis \u00d7 computer vision \u00d7 evidenced modernization \u00b7 2026.06","2013 \ud559\ubd80\ub17c\ubb38 \u00d7 \ucef4\ud4e8\ud130 \ube44\uc804 \u00d7 \uadfc\uac70 \uae30\ubc18 \ud604\ub300\ud654 \u00b7 2026.06"],["My 2013 bachelor-thesis lane departure warning algorithm (OpenCV C/C++, recovered from the printed PDF appendix), faithfully restored in Python with tests and metrics, then modernized one evidenced decision at a time \u2014 ending with a lightweight ML lane regressor that only acts through a segment-agreement gate.","2013\ub144 \ud559\ubd80\ub17c\ubb38\uc758 \ucc28\uc120\uc774\ud0c8\uacbd\ubcf4 \uc54c\uace0\ub9ac\uc998(OpenCV C/C++, \uc778\uc1c4\ub41c PDF \ubd80\ub85d\uc5d0\uc11c \ubcf5\uc6d0)\uc744 \ud14c\uc2a4\ud2b8\uc640 \uc9c0\ud45c\ub97c \uac16\ucd98 Python\uc73c\ub85c \ucda9\uc2e4\ud788 \uc7ac\ud604\ud588\uc2b5\ub2c8\ub2e4. \uc774\ud6c4 \uadfc\uac70\ub97c \ud655\uc778\ud558\uba70 \ud55c \ub2e8\uacc4\uc529 \ud604\ub300\ud654\ud588\uace0, \ucd5c\uc885\uc801\uc73c\ub85c \uad6c\uac04 \ud569\uc758 \uac8c\uc774\ud2b8\ub97c \ud1b5\uacfc\ud560 \ub54c\ub9cc \uc791\ub3d9\ud558\ub294 \uacbd\ub7c9 ML \ucc28\uc120 \ud68c\uadc0 \ubaa8\ub378\ub85c \ubc1c\uc804\uc2dc\ucf30\uc2b5\ub2c8\ub2e4."],["Restored a bachelor-thesis algorithm from 13 years ago \u2192 measured where its assumptions break \u2192 modernized it based on evidence. Explore it alongside a four-panel comparison video.","13\ub144 \uc804 \ud559\ubd80\ub17c\ubb38 \uc54c\uace0\ub9ac\uc998\uc744 \ubcf5\uc6d0 \u2192 \uac00\uc815\uc774 \uae68\uc9c0\ub294 \uc9c0\uc810\uc744 \uacc4\uce21 \u2192 \uadfc\uac70 \uae30\ubc18 \ud604\ub300\ud654. 4\ud328\ub110 \ube44\uad50 \uc601\uc0c1\uacfc \ud568\uaed8 \ubd05\ub2c8\ub2e4."],["restoration","\ubcf5\uc6d0"],["golden-frame eval","\uae30\uc900 \ud504\ub808\uc784 \ud3c9\uac00"],["gated ML","\uac8c\uc774\ud2b8\ub97c \ud1b5\ud55c ML \uc801\uc6a9"],["construction-cost-ml \u2014 an analysis methodology tested on Kaggle data","construction-cost-ml \u2014 \uce90\uae00 \ub370\uc774\ud130\ub85c \uac80\uc99d\ud55c \ub370\uc774\ud130 \ubd84\uc11d \ubc29\ubc95\ub860"],["kaggle dataset \u00d7 analysis methodology \u00d7 honest evaluation \u00b7 2026.07","Kaggle \ub370\uc774\ud130\uc14b \u00d7 \ubd84\uc11d \ubc29\ubc95\ub860 \u00d7 \uc815\uc9c1\ud55c \ud3c9\uac00 \u00b7 2026.07"],["A methodology-first case study: one analysis playbook \u2014 business problem reframing \u2192 EDA with one-line interpretations \u2192 deliberate preprocessing trade-offs \u2192 model comparison \u2192 business judgment \u2014 applied end-to-end to a Kaggle construction-cost dataset, then stress-tested on 36K rows of real gas-turbine sensor data. The cost of median imputation is quantified by controlled ablation (~3k RMSE), 13 models are measured from linear baselines to TabPFN v2 and a hand-built MLX FT-Transformer, and temporal splits expose the random-split mirage (3.9 \u2192 10.1 RMSE) \u2014 misses reported honestly.","\ubc29\ubc95\ub860 \uc911\uc2ec \uc0ac\ub840 \uc5f0\uad6c\uc785\ub2c8\ub2e4. \uc5c5\ubb34 \uad00\uc810\uc758 \ubb38\uc81c \uc7ac\uc815\uc758 \u2192 \ud55c \uc904 \ud574\uc11d\uc744 \uacc1\ub4e4\uc778 EDA \u2192 \uc804\ucc98\ub9ac \uc120\ud0dd\uc758 \uc7a5\ub2e8\uc810 \u2192 \ubaa8\ub378 \ube44\uad50 \u2192 \uc5c5\ubb34 \ud310\ub2e8\uc774\ub77c\ub294 \ud558\ub098\uc758 \ubd84\uc11d \uc808\ucc28\ub97c Kaggle \uac74\uc124\ube44 \ub370\uc774\ud130\uc5d0 \ub05d\uae4c\uc9c0 \uc801\uc6a9\ud55c \ub4a4, \uc2e4\uc81c \uac00\uc2a4\ud130\ube48 \uc13c\uc11c 36K\ud589\uc73c\ub85c \ub2e4\uc2dc \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4. \ud1b5\uc81c\ub41c \uc81c\uac70 \uc2e4\ud5d8\uc73c\ub85c \uc911\uc559\uac12 \ub300\uce58\uc758 \ube44\uc6a9(~3k RMSE)\uc744 \uc815\ub7c9\ud654\ud558\uace0, \uc120\ud615 \uae30\uc900 \ubaa8\ub378\ubd80\ud130 TabPFN v2\uc640 \uc9c1\uc811 \uad6c\ud604\ud55c MLX FT-Transformer\uae4c\uc9c0 13\uc885\uc744 \uce21\uc815\ud588\uc2b5\ub2c8\ub2e4. \uc2dc\uac04\ubd84\ud560 \uac80\uc99d\uc73c\ub85c \ub79c\ub364 \ubd84\ud560\uc758 \uc2e0\uae30\ub8e8(3.9 \u2192 10.1 RMSE)\ub97c \ub4dc\ub7ec\ub0b4\uace0 \uae30\uc900 \ubbf8\ub2ec\ub3c4 \uc815\uc9c1\ud558\uac8c \ubcf4\uace0\ud569\ub2c8\ub2e4."],["An end-to-end analysis-methodology case study on Kaggle construction costs: business-language problem framing, quantified preprocessing costs (missing-value imputation \u22483k RMSE in a reproducible experiment), measurements of 13 models, and revalidation on 36K rows of real sensor data. Temporal extrapolation quantifies the random-split mirage, and below-target results are reported honestly. Every number comes from execution artifacts (0 invented), with advance red-team review.","\uce90\uae00 \uac74\uc124\ube44 \ub370\uc774\ud130\uc5d0 \ub370\uc774\ud130 \ubd84\uc11d \ubc29\ubc95\ub860\uc744 \ub05d\uae4c\uc9c0 \uc801\uc6a9\ud55c \ucf00\uc774\uc2a4 \uc2a4\ud130\ub514 \u2014 \ubb38\uc81c\uc758 \uc5c5\ubb34 \uc5b8\uc5b4 \uc7ac\uc815\uc758\ubd80\ud130 \uc804\ucc98\ub9ac \uc120\ud0dd\uc758 \ube44\uc6a9 \uc815\ub7c9\ud654(\uacb0\uce21 \ub300\uce58 \u22483\ucc9c RMSE, \uc7ac\ud604 \uc2e4\ud5d8), 13\uc885 \ubaa8\ub378 \uc2e4\uce21, \uc2e4\ubb3c \uc13c\uc11c \ub370\uc774\ud130(36K\ud589) \uc7ac\uac80\uc99d\uae4c\uc9c0. \uc2dc\uac04\uc678\uc0bd \uac80\uc99d\uc73c\ub85c \ub79c\ub364 \ubd84\ud560\uc758 \uc2e0\uae30\ub8e8\ub97c \uc815\ub7c9\ud654\ud558\uace0, \uae30\uc900 \ubbf8\ub2ec\uc740 \uc815\uc9c1\ud558\uac8c \ubcf4\uace0. \ubaa8\ub4e0 \uc218\uce58\ub294 \uc2e4\ud589 \uc0b0\ucd9c\ubb3c\uc5d0\uc11c\ub9cc \uc778\uc6a9(\ucc3d\uc791 0), \ub808\ub4dc\ud300 \uc0ac\uc804 \uac80\uc99d."],["Kaggle dataset","Kaggle \ub370\uc774\ud130\uc14b"],["MLX transformer","MLX \ud2b8\ub79c\uc2a4\ud3ec\uba38"],["temporal validation","\uc2dc\uac04\ubd84\ud560 \uac80\uc99d"],["red-team QA","\ub808\ub4dc\ud300 \ud488\uc9c8 \uac80\uc99d"],["Engineering \u00d7 AI","\uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \u00d7 AI"],["Turning power-plant domain knowledge into verifiable AI tools","\ubc1c\uc804 \ud50c\ub79c\ud2b8 \ub3c4\uba54\uc778 \uc9c0\uc2dd\uc744 \uac80\uc99d \uac00\ub2a5\ud55c AI \ub3c4\uad6c\ub85c \ub9cc\ub4e0 \ud504\ub85c\uc81d\ud2b8"],["deterministic engineering calc \u00d7 MCP \u00d7 evidence envelope \u00b7 2026.01\u2013","\uacb0\uc815\ub860\uc801 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \uacc4\uc0b0 \u00d7 MCP \u00d7 \uadfc\uac70\ub97c \ub2f4\uc740 \uc751\ub2f5 \u00b7 2026.01\u2013"],["An MCP server of standards-traceable CCPP balance-of-plant calculations: pipe sizing (ASME B36.10M/B31.1), hydraulics (Crane TP-410, Colebrook), pump TDH/NPSHa (HI), control-valve Cv (ISA 75.01), and an own IAPWS-IF97 steam implementation locked by the official verification tables. Every response carries its evidence \u2014 standard, equation, assumptions, warnings \u2014 and 524 tests plus ~1,800 cross-assertions against independent libraries hold every number. A real Claude client runs a fuel-oil system design verification end to end.","\ud45c\uc900\uc744 \ucd94\uc801\ud560 \uc218 \uc788\ub294 \ubcf5\ud569\ud654\ub825 \uc8fc\ubcc0\uc124\ube44 \uacc4\uc0b0\uc6a9 MCP \uc11c\ubc84\uc785\ub2c8\ub2e4. \ubc30\uad00 \uc0ac\uc774\uc9d5(ASME B36.10M/B31.1), \uc218\ub9ac \uacc4\uc0b0(Crane TP-410, Colebrook), \ud38c\ud504 TDH/NPSHa(HI), \uc81c\uc5b4\ubc38\ube0c Cv(ISA 75.01), \uacf5\uc2dd \uac80\uc99d\ud45c\ub85c \uace0\uc815\ud55c \uc790\uccb4 IAPWS-IF97 \uc99d\uae30 \ubb3c\uc131\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \ubaa8\ub4e0 \uc751\ub2f5\uc5d0 \ud45c\uc900\u00b7\uc218\uc2dd\u00b7\uac00\uc815\u00b7\uacbd\uace0\uac00 \ub2f4\uae30\uba70, 524\uac1c \ud14c\uc2a4\ud2b8\uc640 \ub3c5\ub9bd \ub77c\uc774\ube0c\ub7ec\ub9ac \ub300\ube44 \uc57d 1,800\uac1c \uad50\ucc28 \uac80\uc99d\uc774 \uc218\uce58\ub97c \ub4b7\ubc1b\uce68\ud569\ub2c8\ub2e4. \uc2e4\uc81c Claude \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc5f0\ub8cc\uc720 \uc2dc\uc2a4\ud15c \uc124\uacc4 \uac80\uc99d\uc744 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \uc218\ud589\ud569\ub2c8\ub2e4."],["A practical calculation MCP built solely from power-plant domain knowledge and public standards (Crane\u00b7ASME\u00b7HI\u00b7ISA\u00b7ASTM\u00b7IAPWS). The LLM orchestrates; verified code computes. Every response includes standards, equations, assumptions and warnings. The published evidence even records transcription errors caught by the validation harness.","\ubc1c\uc804 \ub3c4\uba54\uc778 \uc9c0\uc2dd\uacfc \uacf5\uac1c \ud45c\uc900(Crane\u00b7ASME\u00b7HI\u00b7ISA\u00b7ASTM\u00b7IAPWS)\ub9cc\uc73c\ub85c \uad6c\ucd95\ud55c \uc2e4\ubb34\uc6a9 \uacc4\uc0b0 MCP. LLM\uc740 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158\ub9cc, \uc22b\uc790\ub294 \uac80\uc99d\ub41c \ucf54\ub4dc\uac00 \u2014 \ubaa8\ub4e0 \uc751\ub2f5\uc5d0 \uadfc\uac70 \ud45c\uc900\u00b7\uc218\uc2dd\u00b7\uac00\uc815\u00b7\uacbd\uace0\uac00 \uc2e4\ub824 \uc635\ub2c8\ub2e4. \uac80\uc99d \ud558\ub2c8\uc2a4\uac00 \uc2e4\uc81c \uc804\uc0ac \uc624\ub958\ub97c \uc7a1\uc544\ub0b8 \uae30\ub85d\uae4c\uc9c0 \uc99d\uac70\ub85c \uacf5\uac1c."],["IAPWS-IF97 own impl","IAPWS-IF97 \uc790\uccb4 \uad6c\ud604"],["524 tests","524\uac1c \ud14c\uc2a4\ud2b8"],["cross-validated","\uad50\ucc28 \uac80\uc99d \uc644\ub8cc"],["Actual Claude E2E transcript \u2192","\uc2e4\uc81c Claude E2E \ud2b8\ub79c\uc2a4\ud06c\ub9bd\ud2b8 \u2192"],["INTERNAL \u00b7 CONCEPT PRESENTATION","\uc0ac\ub0b4 \ub3c4\uad6c \u00b7 \uac1c\ub150 \uc18c\uac1c"],["TBE review & reply agent","TBE \uac80\ud1a0\u00b7\ub2f5\ubcc0 \uc5d0\uc774\uc804\ud2b8"],["engineering judgment \u00d7 evidence \u00d7 AI","\uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ud310\ub2e8 \u00d7 \uadfc\uac70 \u00d7 AI"],["An internal tool that structures requirements and vendor responses, retrieves evidence, and helps draft reviews and replies. Illustrative interactions explain the workflow in place of actual documents or training data. The responsible engineer makes the final judgment.","\uc694\uad6c\uc0ac\ud56d\uacfc \uc5c5\uccb4 \ub2f5\ubcc0\uc744 \uad6c\uc870\ud654\ud558\uace0, \uadfc\uac70\ub97c \ucc3e\uc544 \uac80\ud1a0\uc640 \ub2f5\ubcc0 \ucd08\uc548\uc744 \ub3d5\ub294 \uc0ac\ub0b4 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \uc2e4\uc81c \ubb38\uc11c\uc640 \ud559\uc2b5 \ub370\uc774\ud130 \ub300\uc2e0 \uc124\uba85\uc6a9 \uc778\ud130\ub799\uc158\uc73c\ub85c \uc791\uc5c5 \ud750\ub984\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ucd5c\uc885 \ud310\ub2e8\uc740 \ub2f4\ub2f9 \uc5d4\uc9c0\ub2c8\uc5b4\uac00 \uc218\ud589\ud569\ub2c8\ub2e4."],["AI Agent Systems","AI \uc5d0\uc774\uc804\ud2b8 \uc2dc\uc2a4\ud15c"],["Running agents as a team and building a runtime for air-gapped environments","\uc5d0\uc774\uc804\ud2b8\ub97c \ud300\uc73c\ub85c \uc6b4\uc601\ud558\uace0, \ud3d0\uc1c4\ub9dd\uc6a9 \ub7f0\ud0c0\uc784\uc744 \uc9c1\uc811 \uad6c\ud604\ud55c \uae30\ub85d"],["NEW","\uc2e0\uaddc"],["FONTIS \u2014 grounded real-estate report RAG","FONTIS \u2014 \uadfc\uac70 \uae30\ubc18 \ubd80\ub3d9\uc0b0 \ubcf4\uace0\uc11c RAG"],["multimodal PDF RAG \u00d7 hybrid retrieval \u00d7 cited refusal \u00b7 2026.08","\uba40\ud2f0\ubaa8\ub2ec PDF RAG \u00d7 \ud558\uc774\ube0c\ub9ac\ub4dc \uac80\uc0c9 \u00d7 \uadfc\uac70\ub97c \uc81c\uc2dc\ud558\ub294 \uac70\ubd80 \u00b7 2026.08"],["Three Korean real-estate reports become 401 citation-preserving evidence chunks, searched with BM25 + FAISS and fused by RRF before grounded Q&A.","\ud55c\uad6d \ubd80\ub3d9\uc0b0 \ubcf4\uace0\uc11c 3\uac1c\ub97c \uc778\uc6a9 \uc815\ubcf4\ub97c \ubcf4\uc874\ud55c \uadfc\uac70 \uccad\ud06c 401\uac1c\ub85c \uad6c\uc131\ud558\uace0, BM25 + FAISS\ub85c \uac80\uc0c9\ud55c \uacb0\uacfc\ub97c RRF\ub85c \uacb0\ud569\ud574 \uadfc\uac70 \uae30\ubc18 \uc9c8\uc758\uc751\ub2f5\uc5d0 \ud65c\uc6a9\ud569\ub2c8\ub2e4."],["Structured 136 pages from 3 institutions into 215 text, 49 table and 137 image-evidence chunks. Retrieved all expected evidence for 21 of 23 questions (anchor recall 0.9565), and refused all 5/5 questions with insufficient evidence. 21/23 measures retrieval coverage, not answer accuracy.","3\uac1c \uae30\uad00\u00b7136\ud398\uc774\uc9c0\ub97c \ud14d\uc2a4\ud2b8 215, \ud45c 49, \uc774\ubbf8\uc9c0 \uadfc\uac70 137\uac1c\ub85c \uad6c\uc870\ud654. 23\ubb38\ud56d \uc911 21\ubb38\ud56d\uc5d0\uc11c \uae30\ub300 \uadfc\uac70 \uc804\uccb4\ub97c \ud68c\uc218(anchor recall 0.9565)\ud588\uace0, \uadfc\uac70 \ubd80\uc871 5\ubb38\ud56d\uc740 5/5 \uac70\ubd80\ud588\uc2b5\ub2c8\ub2e4. 21/23\uc740 retrieval coverage\uc774\uba70 answer accuracy\uac00 \uc544\ub2d9\ub2c8\ub2e4."],["multimodal chunks","\uba40\ud2f0\ubaa8\ub2ec \uccad\ud06c"],["page citations","\ud398\uc774\uc9c0 \uc778\uc6a9"],["refusal gate","\uac70\ubd80 \uac8c\uc774\ud2b8"],["offline full-stack document AI \u00d7 LangGraph agent \u00b7 2025.11\u20132026.07","\uc624\ud504\ub77c\uc778 \ud480\uc2a4\ud0dd \ubb38\uc11c AI \u00d7 LangGraph \uc5d0\uc774\uc804\ud2b8 \u00b7 2025.11\u20132026.07"],["An offline-capable full-stack desktop web app for engineering documents \u2014 FastAPI + React, packaged as a single PyInstaller exe \u2014 with four chained modules (translate / analyze / review / write) running on any OpenAI-compatible gateway. Later evolved with a declarative LangGraph agent that reviews specification deviations: the whole workflow is declared in YAML, with ambiguity branching, LLM self-correction, and deterministic tool validation \u2014 tools over tokens.","\uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ubb38\uc11c\uc6a9 \uc624\ud504\ub77c\uc778 \uc9c0\uc6d0 \ud480\uc2a4\ud0dd \ub370\uc2a4\ud06c\ud1b1 \uc6f9\uc571\uc785\ub2c8\ub2e4. FastAPI + React\ub97c \ub2e8\uc77c PyInstaller exe\ub85c \ud328\ud0a4\uc9d5\ud558\uace0, \ubc88\uc5ed\u00b7\ubd84\uc11d\u00b7\uac80\ud1a0\u00b7\uc791\uc131\uc758 4\uac1c \ubaa8\ub4c8\uc744 \uc5f0\uacb0\ud574 \ubaa8\ub4e0 OpenAI \ud638\ud658 \uac8c\uc774\ud2b8\uc6e8\uc774\uc5d0\uc11c \uc2e4\ud589\ud569\ub2c8\ub2e4. \uc774\ud6c4 \uc0ac\uc591 \uc774\ud0c8\uc744 \uac80\ud1a0\ud558\ub294 \uc120\uc5b8\uc801 LangGraph \uc5d0\uc774\uc804\ud2b8\ub85c \ubc1c\uc804\uc2dc\ucf30\uc2b5\ub2c8\ub2e4. \uc804\uccb4 \uc6cc\ud06c\ud50c\ub85c\ub97c YAML\ub85c \uc120\uc5b8\ud558\uace0 \ubaa8\ud638\uc131 \ubd84\uae30, LLM \uc790\uac00\ubcf4\uc815, \uacb0\uc815\ub860\uc801 \ub3c4\uad6c \uac80\uc99d\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4. \uc6d0\uce59\uc740 tools over tokens\uc785\ub2c8\ub2e4."],["Built an engineering-document app (FastAPI + React, a single exe) that runs in a browser even on an air-gapped network, then evolved it into a declarative LangGraph agent. YAML workflows, ambiguity branches, LLM self-correction and deterministic tool validation \u2014 an anonymized public release of an internal competition entry.","\ud3d0\uc1c4\ub9dd\uc5d0\uc11c\ub3c4 \ube0c\ub77c\uc6b0\uc800 \ud558\ub098\ub85c \ub3c4\ub294 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ubb38\uc11c \ucc98\ub9ac \uc571(FastAPI+React, \ub2e8\uc77c exe)\uc744 \ub9cc\ub4e4\uace0, \uc774\ub97c \uc120\uc5b8\uc801 LangGraph \uc5d0\uc774\uc804\ud2b8\ub85c \uc9c4\ud654\uc2dc\ud0a8 \uae30\ub85d. \uc6cc\ud06c\ud50c\ub85c\ub97c YAML\ub85c \uc120\uc5b8\ud558\uace0 \uc560\ub9e4 \ucf00\uc774\uc2a4 \ubd84\uae30\u00b7LLM \uc790\uac00\ubcf4\uc815\u00b7\uacb0\uc815\ub860 \ub3c4\uad6c \uac80\uc99d\uae4c\uc9c0 \u2014 \uc0ac\ub0b4 \uacbd\uc9c4\ub300\ud68c \ucd9c\ud488\uc791\uc744 \uc775\uba85\ud654\ud574 \uacf5\uac1c."],["PyInstaller exe","PyInstaller \uc2e4\ud589\ud30c\uc77c"],["air-gapped","\ud3d0\uc1c4\ub9dd \uc9c0\uc6d0"],["LangGraph agent \u2192","LangGraph \uc5d0\uc774\uc804\ud2b8 \u2192"],["Kaggle simulation \u00d7 dual-agent orchestration \u00b7 2026.05","Kaggle \uc2dc\ubbac\ub808\uc774\uc158 \u00d7 \ub450 \uc5d0\uc774\uc804\ud2b8 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158 \u00b7 2026.05"],["A 2-day sprint in Kaggle's Maze Crawler real-time strategy competition, where a Claude + Codex agent team did all research, coding, experiments and submission decisions under human orchestration \u2014 tty bridge, file mailbox, submission locks, adversarial audit, 200-seed gates. Finished 131/459 (top 29%, 906.4 pts), with honest negative results logged along the way.","Kaggle Maze Crawler \uc2e4\uc2dc\uac04 \uc804\ub7b5 \ub300\ud68c\uc5d0 \uc774\ud2c0\uac04 \ucc38\uc5ec\ud588\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\uc758 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158 \uc544\ub798 Claude + Codex \ud300\uc774 tty \ube0c\ub9ac\uc9c0, \ud30c\uc77c \uc6b0\ud3b8\ud568, \uc81c\ucd9c \ub77d, \uc801\ub300\uc801 \uac10\uc0ac, 200-seed \uac8c\uc774\ud2b8\ub97c \ud65c\uc6a9\ud574 \ub9ac\uc11c\uce58\u00b7\ucf54\ub529\u00b7\uc2e4\ud5d8\u00b7\uc81c\ucd9c \ud310\ub2e8\uc744 \ubaa8\ub450 \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4. \ucd5c\uc885 131/459(\uc0c1\uc704 29%, 906.4\uc810)\ub85c \ub9c8\uac10\ud588\uace0, \uacfc\uc815\uc758 \ubd80\uc815 \uacb0\uacfc\ub3c4 \uc815\uc9c1\ud558\uac8c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4."],["Split two AI agents into implementation and adversarial-audit roles, coordinating them with a communication protocol, submission locks and decision logs to reach the top 29% in two days. The working directory is published unedited, including the record of the day that ended with 0/5 submissions.","\ub450 AI \uc5d0\uc774\uc804\ud2b8\uc5d0 \uc5ed\ud560(\uad6c\ud604 vs \uc801\ub300\uc801 \uac10\uc0ac)\uc744 \ub098\ub204\uace0 \ud1b5\uc2e0 \ud504\ub85c\ud1a0\ucf5c\u00b7\uc81c\ucd9c \ub77d\u00b7\uc758\uc0ac\uacb0\uc815 \ub85c\uadf8\ub85c \uc6b4\uc601\ud574, \uc774\ud2c0 \ub9cc\uc5d0 \uc0c1\uc704 29% \ub2ec\uc131. \uc791\uc5c5 \ub514\ub809\ud130\ub9ac\ub97c \ubb34\ud3b8\uc9d1 \uacf5\uac1c \u2014 \"\uc81c\ucd9c 0/5\ub85c \ub9c8\uac10\ud55c \ub0a0\"\uc758 \uae30\ub85d\uae4c\uc9c0 \uadf8\ub300\ub85c \uc788\uc2b5\ub2c8\ub2e4."],["Kaggle top 29%","Kaggle \uc0c1\uc704 29%"],["200-seed gates","200-seed \uac80\uc99d \uac8c\uc774\ud2b8"],["decision logs","\uc758\uc0ac\uacb0\uc815 \ub85c\uadf8"],["Agent gameplay replay \u2192","\uc5d0\uc774\uc804\ud2b8 \ud50c\ub808\uc774 \ub9ac\ud50c\ub808\uc774 \u2192"],["LLM agent runtime, stdlib-only \u00b7 2026.06\u2013","LLM \uc5d0\uc774\uc804\ud2b8 \ub7f0\ud0c0\uc784, \ud45c\uc900 \ub77c\uc774\ube0c\ub7ec\ub9ac \uc804\uc6a9 \u00b7 2026.06\u2013"],["A single-file LLM agent runtime built for constrained corporate environments where nothing can be pip-installed: agent loop with native tool-calling, depth-limited subagents, context compaction, file-based memory, a safety router, and document-generation pipelines (pptx/docx/xlsx) \u2014 Python standard library only, works with any OpenAI-compatible gateway.","pip \uc124\uce58\uac00 \ubd88\uac00\ub2a5\ud55c \uc81c\ud55c\ub41c \uc0ac\ub0b4 \ud658\uacbd\uc744 \uc704\ud574 \ub9cc\ub4e0 \ub2e8\uc77c \ud30c\uc77c LLM \uc5d0\uc774\uc804\ud2b8 \ub7f0\ud0c0\uc784\uc785\ub2c8\ub2e4. \ub124\uc774\ud2f0\ube0c \ub3c4\uad6c \ud638\ucd9c\uc744 \uc0ac\uc6a9\ud558\ub294 \uc5d0\uc774\uc804\ud2b8 \ub8e8\ud504, \uae4a\uc774\ub97c \uc81c\ud55c\ud55c \uc11c\ube0c\uc5d0\uc774\uc804\ud2b8, \ucee8\ud14d\uc2a4\ud2b8 \uc555\ucd95, \ud30c\uc77c \uae30\ubc18 \uba54\ubaa8\ub9ac, \uc548\uc804 \ub77c\uc6b0\ud130, \ubb38\uc11c \uc0dd\uc131 \ud30c\uc774\ud504\ub77c\uc778(pptx/docx/xlsx)\uc744 Python \ud45c\uc900 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub9cc\uc73c\ub85c \uad6c\ud604\ud588\uace0, \ubaa8\ub4e0 OpenAI \ud638\ud658 \uac8c\uc774\ud2b8\uc6e8\uc774\uc5d0\uc11c \ub3d9\uc791\ud569\ub2c8\ub2e4."],["An agent runtime implemented entirely with the standard library for air-gapped environments where external packages cannot be installed. Used in practice with an internal LLM gateway.","\uc678\ubd80 \ud328\ud0a4\uc9c0 \uc124\uce58\uac00 \ub9c9\ud78c \ud3d0\uc1c4\ub9dd\uc5d0\uc11c \ud45c\uc900 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub9cc\uc73c\ub85c \uad6c\ud604\ud55c \uc5d0\uc774\uc804\ud2b8 \ub7f0\ud0c0\uc784. \uc0ac\ub0b4 LLM \uac8c\uc774\ud2b8\uc6e8\uc774 \ud658\uacbd\uc5d0\uc11c \uc2e4\uc0ac\uc6a9."],["Python stdlib","Python \ud45c\uc900 \ub77c\uc774\ube0c\ub7ec\ub9ac"],["tool-calling","\ub3c4\uad6c \ud638\ucd9c"],["subagents","\uc11c\ube0c\uc5d0\uc774\uc804\ud2b8"],["AI Enablement","AI \ud65c\uc6a9 \ud655\uc0b0"],["Helping organizations use AI in practice \u2014 training and data boundaries","\uc870\uc9c1\uc774 AI\ub97c \uc2e4\uc81c\ub85c \uc4f0\uac8c \ub9cc\ub4dc\ub294 \uc77c \u2014 \uad50\uc721\uacfc \ub370\uc774\ud130 \uacbd\uacc4"],["AI onboarding \u00d7 non-developers \u00b7 2026.04","AI \uc628\ubcf4\ub529 \u00d7 \ube44\uac1c\ubc1c\uc790 \u00b7 2026.04"],["An 80-minute Claude curriculum designed and delivered for non-developer colleagues: product landscape (Claude.ai / Desktop / Code), file-upload analysis demos, Project \u00b7 MCP \u00b7 Skill concepts \u2014 with a synthetic demo dataset and a working report-writing Skill, packaged so attendees could retry everything on their own.","\ube44\uac1c\ubc1c\uc790 \ub3d9\ub8cc\ub97c \uc704\ud574 \uc9c1\uc811 \uc124\uacc4\ud558\uace0 \uc9c4\ud589\ud55c 80\ubd84 Claude \uad50\uc721\uc785\ub2c8\ub2e4. \uc81c\ud488 \uad6c\uc131(Claude.ai / Desktop / Code), \ud30c\uc77c \uc5c5\ub85c\ub4dc \ubd84\uc11d \ub370\ubaa8, Project\u00b7MCP\u00b7Skill \uac1c\ub150\uc744 \ub2e4\ub8f9\ub2c8\ub2e4. \ud569\uc131 \uc2e4\uc2b5 \ub370\uc774\ud130\uc640 \uc2e4\uc81c \uc791\ub3d9\ud558\ub294 \ubcf4\uace0\uc11c \uc791\uc131 Skill\uc744 \ud568\uaed8 \uc81c\uacf5\ud574 \uc218\uac15\uc790\uac00 \uc2a4\uc2a4\ub85c \ubaa8\ub4e0 \uc2e4\uc2b5\uc744 \ub2e4\uc2dc \ud574\ubcfc \uc218 \uc788\ub3c4\ub85d \uad6c\uc131\ud588\uc2b5\ub2c8\ub2e4."],["Designed and taught an 80-minute curriculum for non-developer colleagues. The goal was a shift in perspective: reuse recurring work as data + working rules + output format, beyond a single prompt. The public package includes synthetic practice datasets, a report Skill example and multi-LLM collaboration logs from its creation.","\ube44\uac1c\ubc1c\uc790 \uc2e4\ubb34 \ub3d9\ub8cc\ub4e4\uc744 \uc704\ud574 80\ubd84 \ucee4\ub9ac\ud058\ub7fc\uc744 \uc9c1\uc811 \uc124\uacc4\ud574 \uac15\uc758. \ubaa9\ud45c\ub294 \uad00\uc810 \uc804\ud658 \u2014 \"\ubc18\ubcf5 \uc5c5\ubb34\ub97c \ud504\ub86c\ud504\ud2b8 \ud55c \ubc88\uc774 \uc544\ub2c8\ub77c \ub370\uc774\ud130 + \uc791\uc5c5 \uaddc\uce59 + \uc0b0\ucd9c\ubb3c \ud615\uc2dd\uc73c\ub85c \uc7ac\uc0ac\uc6a9\ud55c\ub2e4\". \uc2e4\uc2b5\uc6a9 \ud569\uc131 \ub370\uc774\ud130\uc14b, \ubcf4\uace0\uc11c Skill \uc608\uc81c, \uc81c\uc791 \uacfc\uc815\uc758 \uba40\ud2f0-LLM \ud611\uc5c5 \ub85c\uadf8\uae4c\uc9c0 \ud328\ud0a4\uc9c0\ub85c \uacf5\uac1c."],["80-min curriculum","80\ubd84 \ucee4\ub9ac\ud058\ub7fc"],["demo datasets","\ub370\ubaa8 \ub370\uc774\ud130\uc14b"],["report Skill example","report Skill \uc608\uc81c"],["multi-LLM log","\uba40\ud2f0 LLM \ub85c\uadf8"],["Presentation slides \u2192","\ubc1c\ud45c \uc2ac\ub77c\uc774\ub4dc \u2192"],["Learner onboarding \u2192","\uc218\uac15\uc790 \uc628\ubcf4\ub529 \u2192"],["internal-data readiness \u00d7 LLM masking \u00b7 2026.04","\uc0ac\ub0b4 \ub370\uc774\ud130 \ud65c\uc6a9 \uc900\ube44 \u00d7 LLM \ub9c8\uc2a4\ud0b9 \u00b7 2026.04"],["A synthetic demo of privacy-aware prompt boundaries for internal-data analysis and LLM workflows: semantic placeholders, metadata hints, placeholder validation, and local restore mapping. No internal data or external API calls are included.","\uc0ac\ub0b4 \ub370\uc774\ud130 \ubd84\uc11d\uacfc LLM \uc6cc\ud06c\ud50c\ub85c\ub97c \uc704\ud55c \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638 \uc911\uc2ec \ud504\ub86c\ud504\ud2b8 \uacbd\uacc4\ub97c \ud569\uc131 \ub370\uc774\ud130\ub85c \uc2dc\uc5f0\ud569\ub2c8\ub2e4. \uc758\ubbf8\ub97c \ub2f4\uc740 \ud50c\ub808\uc774\uc2a4\ud640\ub354, \uba54\ud0c0\ub370\uc774\ud130 \ud78c\ud2b8, \ud50c\ub808\uc774\uc2a4\ud640\ub354 \uac80\uc99d, \ub85c\uceec \ubcf5\uc6d0 \ub9e4\ud551\uc744 \ub2e4\ub8f9\ub2c8\ub2e4. \uc0ac\ub0b4 \ub370\uc774\ud130\ub098 \uc678\ubd80 API \ud638\ucd9c\uc740 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."],["A companion project using synthetic examples to demonstrate masking and de-identification boundaries before connecting internal or sensitive information to AI analysis and LLM workflows, so original values are not sent directly to external models.","\uc0ac\ub0b4/\ubbfc\uac10 \uc815\ubcf4\ub97c AI \ubd84\uc11d\uacfc LLM \ud65c\uc6a9\uc5d0 \uc5f0\uacb0\ud558\uae30 \uc804\uc5d0, \uc6d0\ubb38 \uac12\uc744 \uc9c1\uc811 \uc678\ubd80 \ubaa8\ub378\uc5d0 \ubcf4\ub0b4\uc9c0 \uc54a\uae30 \uc704\ud55c \ub9c8\uc2a4\ud0b9\u00b7\ube44\uc2dd\ubcc4\ud654 \uacbd\uacc4\ub97c \ud569\uc131 \uc608\uc2dc\ub85c \uc2dc\uc5f0\ud55c \ubcf4\uc870 \ud504\ub85c\uc81d\ud2b8."],["semantic placeholders","\uc758\ubbf8\ub97c \ub2f4\uc740 \ud50c\ub808\uc774\uc2a4\ud640\ub354"],["local restore","\ub85c\uceec \ubcf5\uc6d0"],["synthetic data","\ud569\uc131 \ub370\uc774\ud130"],["privacy-aware workflow","\uac1c\uc778\uc815\ubcf4\ub97c \uace0\ub824\ud55c \uc6cc\ud06c\ud50c\ub85c"],["Side Experiments","\uc0ac\uc774\ub4dc \uc2e4\ud5d8"],["Evening experiments beyond the day job \u2014 small, frequent, and shipped","\ubcf8\uc5c5 \ubc16 \uc800\ub141 \uc2e4\ud5d8 \u2014 \uc791\uac8c, \uc790\uc8fc, \ubc30\ud3ec\uae4c\uc9c0 \ub05d\ub0b4\ubcf4\uae30"],["2025.12 \u00b7 single-file HTML \u00b7 Gemini API","2025.12 \u00b7 \ub2e8\uc77c HTML \u00b7 Gemini API"],["A mobile Spanish pronunciation app integrating Gemini 2.5 (generation + TTS) in a single HTML file. API keys are stored only in browser localStorage. Improved across 3 iterations in one week, from a verb trainer to a reading app.","Gemini 2.5(\uc0dd\uc131 + TTS)\ub97c \ub2e8\uc77c HTML\uc5d0 \ud1b5\ud569\ud55c \ubaa8\ubc14\uc77c \uc2a4\ud398\uc778\uc5b4 \ubc1c\uc74c \ud559\uc2b5 \uc571. API \ud0a4\ub294 \ube0c\ub77c\uc6b0\uc800 localStorage\uc5d0\ub9cc \uc800\uc7a5. \ub3d9\uc0ac \ud2b8\ub808\uc774\ub108 \u2192 \ub9ac\ub529 \uc571\uc73c\ub85c 1\uc8fc\uac04 3\ud68c \ubc18\ubcf5 \uac1c\uc120."],["Live demo \u2192","\ub77c\uc774\ube0c \ub370\ubaa8 \u2192"],["Verb trainer (predecessor) \u2192","\ub3d9\uc0ac \ud2b8\ub808\uc774\ub108(\uc804\uc2e0) \u2192"],["Source \u2192","\uc18c\uc2a4 \u2192"],["2025.12 \u00b7 single-file HTML \u00b7 canvas","2025.12 \u00b7 \ub2e8\uc77c HTML \u00b7 canvas"],["A canvas arcade game for mobile and desktop, featuring a cinematic intro, touch and keyboard input, and 0 external libraries (excluding web fonts). Built through paired prototyping with generative AI.","\ubaa8\ubc14\uc77c/PC \uacb8\uc6a9 \uce94\ubc84\uc2a4 \uc544\ucf00\uc774\ub4dc \uac8c\uc784. \uc2dc\ub124\ub9c8\ud2f1 \uc778\ud2b8\ub85c, \ud130\uce58\u00b7\ud0a4\ubcf4\ub4dc \uc785\ub825, \uc678\ubd80 \ub77c\uc774\ube0c\ub7ec\ub9ac 0(\uc6f9\ud3f0\ud2b8 \uc81c\uc678). \uc0dd\uc131\ud615 AI\uc640\uc758 \ud398\uc5b4 \ud504\ub85c\ud1a0\ud0c0\uc774\ud551\uc73c\ub85c \uc81c\uc791."],["Play \u2192","\ud50c\ub808\uc774 \u2192"],["Journey","\uc5ec\uc815"],["A continuous series of experiments","\ud55c \ubc88\uc758 \uc2a4\ud37c\ud2b8\uac00 \uc544\ub2c8\ub77c, \uc774\uc5b4\uc9c4 \uc2dc\ub3c4\ub4e4"],["Bachelor's thesis \u2014 lane-departure-warning CV algorithm","\ud559\ubd80\ub17c\ubb38 \u2014 \ucc28\uc120\uc774\ud0c8\uacbd\ubcf4 CV \uc54c\uace0\ub9ac\uc998"],["The starting point for restoration and modernization 13 years later","13\ub144 \ub4a4 \ubcf5\uc6d0\u00b7\ud604\ub300\ud654\uc758 \ucd9c\ubc1c\uc810"],["docpilot \u2014 offline document AI app (original internal competition entry)","docpilot \u2014 \uc624\ud504\ub77c\uc778 \ubb38\uc11c AI \uc571 (\uc0ac\ub0b4 \uacbd\uc9c4\ub300\ud68c \uc6d0\ubcf8)"],["2026.04 full-stack rebuild \u2192 2026.07 evolution into a langgraph agent","2026.04 \ud480\uc2a4\ud0dd rebuild \u2192 2026.07 langgraph \uc5d0\uc774\uc804\ud2b8\ub85c \uc9c4\ud654"],["Single-HTML Gemini experiments \u2014 learning apps and games","\ub2e8\uc77c HTML Gemini \uc2e4\ud5d8 \u2014 \ud559\uc2b5 \uc571 \u00b7 \uac8c\uc784"],["Evening prototypes to gain hands-on experience with multimodal APIs","\uba40\ud2f0\ubaa8\ub2ec API\ub97c \uc190\uc5d0 \uc775\ud788\ub294 \uc800\ub141 \ud504\ub85c\ud1a0\ud0c0\uc774\ud551"],["Turning engineering calculations into deterministic tools","\uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \uacc4\uc0b0\uc11c\uc758 \uacb0\uc815\ub860\uc801 \ub3c4\uad6c\ud654"],["ccpp-tools-mcp \u2014 the beginning of \u201ctools over tokens\u201d","ccpp-tools-mcp \u2014 \"tools over tokens\"\uc758 \uc2dc\uc791"],["Claude training for non-developer colleagues","\uc0ac\ub0b4 \ube44\uac1c\ubc1c\uc790 \ub300\uc0c1 Claude \uac15\uc758"],["From personal use to organization-wide adoption","\uac1c\uc778 \ud65c\uc6a9\uc744 \uc870\uc9c1 \ud655\uc0b0\uc73c\ub85c"],["watt-agent runtime for air-gapped networks","\ud3d0\uc1c4\ub9dd\uc6a9 \uc5d0\uc774\uc804\ud2b8 \ub7f0\ud0c0\uc784 watt-agent"],["stdlib-only, used with an internal gateway","stdlib-only, \uc0ac\ub0b4 \uac8c\uc774\ud2b8\uc6e8\uc774 \uc2e4\uc0ac\uc6a9"],["permit risk model \u00b7 maze agent team \u00b7 LDW restoration","permit \ub9ac\uc2a4\ud06c \ubaa8\ub378 \u00b7 maze \uc5d0\uc774\uc804\ud2b8 \ud300 \u00b7 LDW \ubcf5\uc6d0"],["Portfolio published","\ud3ec\ud2b8\ud3f4\ub9ac\uc624 \uacf5\uac1c"],["About","\uc18c\uac1c"],["10+ years designing power-plant systems","\ubc1c\uc804\uc18c \uc2dc\uc2a4\ud15c \uc124\uacc4 10+\ub144"],["\u2014 Worked on system design, vendor technical bid evaluation (TBE), field engineering and design management across international combined-cycle projects in power-plant EPC. 2+ years on overseas sites.","\u2014 \ubc1c\uc804\ud50c\ub79c\ud2b8 EPC\uc5d0\uc11c \ub2e4\uc591\ud55c \ud574\uc678 \ubcf5\ud569\ud654\ub825 \ud504\ub85c\uc81d\ud2b8\uc758 \uc2dc\uc2a4\ud15c \uc124\uacc4, \ubca4\ub354 \uae30\uc220\ud3c9\uac00(TBE), \ud604\uc7a5 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1, \uc124\uacc4 \uad00\ub9ac\ub97c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4. \ud574\uc678 \ud604\uc7a5 2\ub144+."],["Building AI as a system","AI\ub294 \ub3c4\uad6c\uac00 \uc544\ub2c8\ub77c \uc2dc\uc2a4\ud15c\uc73c\ub85c"],["\u2014 Alongside engineering design, I designed and implemented internal LLM agent runtimes, MCP tools for engineering calculations, and document-automation pipelines. One principle: deterministic code computes the numbers; the LLM connects and explains their evidence.","\u2014 \uc124\uacc4 \uc5c5\ubb34\uc640 \ubcd1\ud589\ud558\uc5ec LLM \uc5d0\uc774\uc804\ud2b8 \ub7f0\ud0c0\uc784, \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \uacc4\uc0b0\uc758 MCP \ub3c4\uad6c\ud654, \ubb38\uc11c \uc790\ub3d9\ud654 \ud30c\uc774\ud504\ub77c\uc778\uc744 \uc0ac\ub0b4\uc5d0\uc11c \uc9c1\uc811 \uc124\uacc4\u00b7\uad6c\ud604\ud588\uc2b5\ub2c8\ub2e4. \uc6d0\uce59\uc740 \ud558\ub098: \uc22b\uc790\ub294 \uacb0\uc815\ub860\uc801 \ucf54\ub4dc\uac00 \uacc4\uc0b0\ud558\uace0, LLM\uc740 \uadf8 \uadfc\uac70\ub97c \uc5f0\uacb0\ud558\uace0 \uc124\uba85\ud569\ub2c8\ub2e4."],["What's next","\ub2e4\uc74c \ubaa9\ud45c"],["\u2014 Structure schedule, design and risk data from large construction projects, and build AI decision tools that practitioners actually use.","\u2014 \ub300\uaddc\ubaa8 \uac74\uc124 \ud504\ub85c\uc81d\ud2b8\uc758 \uc77c\uc815\u00b7\uc124\uacc4\u00b7\ub9ac\uc2a4\ud06c \ub370\uc774\ud130\ub97c \uad6c\uc870\ud654\ud558\uace0, \ud604\uc5c5\uc774 \uc2e4\uc81c\ub85c \uc4f0\ub294 AI \uc758\uc0ac\uacb0\uc815 \ub3c4\uad6c\ub97c \ub9cc\ub4dc\ub294 \uac83."],["\u00a9 2026 Jinhyun An \u00b7 Built with AI Agents, deployed on GitHub Pages \u00b7","\u00a9 2026 Jinhyun An \u00b7 AI \uc5d0\uc774\uc804\ud2b8\uc640 \ud568\uaed8 \uc81c\uc791, GitHub Pages \ubc30\ud3ec \u00b7"]];
